<script>
import Layout from "../../../layouts/main";
import appConfig from "@/app.config";

export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
  },
  data() {
    return {
      agents: [],
      accounts: [],
      agent: null,
      selectedAccounts: null,
      levelThreeAccountId: null,
      levelThreeAccounts: [],
      filteredAccounts:[],
      filteredAgents:[],
      branchItem: {
        isNew: 1,
        item: {},
        code: null,
        account: null,
        Adaccount: null,
      },
      addExpense: [{}],
      reference_no:null,
      purchase_type:{code:'expenses'},
      fixed_assets:[],
            company_branches: [],
            purchase_order_types:[],
                  user:{}


    };
  },
  methods: {
    selectedAgent(search) {
      this.http
        .post("agents/search", {
          search,
        })
        .then((res) => {
          if (res.status) {
            this.filteredAgents = res.data
          }
        });
    },
    selectedAccount(search) {
      this.http
        .post("level-three-chart-of-accounts-copy-1/accounts-setup/search", {
          search,
          type: "Expense",
          level: 3,
        })
        .then((res) => {
          if (res.status) {
            this.filteredAccounts = res.data
          }
          
        });
    },
    showAccountLabel(one){
      return this.$i18n.locale =='en' ? one.code +' - '+one.name_en : one.code +' - '+one.name
    },
    createPo() {
      console.log("step 67 :",{purchase_order_type:this.purchase_type, agent:this.agent,addExpense:this.addExpense,reference_no:this.reference_no});
      
      this.http
        .post("purchases/purchase", {
          expenses: this.addExpense,
          agent: this.agent,
          reference_no:this.reference_no,
          purchase_order_type:this.purchase_type,
        })
        .then((res) => {
          if (res.status) {
            this.addExpense = [{}];
            this.$router.push("/payments_invoices");
          }
        });
   
   },
    deleteOption(index) {
      this.addExpense.splice(index, 1);
    },
    fixedAssetSearch(search) {
      this.http
        .post("fixed-assets/search", {
          search,
          page: 1,
          limit: 20,
        })
        .then((res) => {
          if (res.status) {
            this.fixed_assets = res.data;
          }
        });
    },
    
    showAssetLabel(one) {
      console.log("step 139 :", one);

      return this.$i18n.locale == "en" ? one.name_en : one.name;
    },
        getBranchSites(branch_id, index) {
      console.log(index);
      return new Promise((resolve)=>{

        this.http
          .post("level-one-chart-of-accounts/get-branch-sites", { branch_id })
          .then((resp) => {
            console.log(resp.data);
             resolve(resp.data);
             this.addExpense[index].branch_sites =resp.data
          });
      })
    },
      getBranches() {
      this.http.get("branches").then((res) => {
        if (res.status) this.company_branches = res.data;
      });
    },
    getPurchaseOrderTypes (){
      this.http.get('purchases/purchase-order-types').then((res)=>{
        if(res.status){
          this.purchase_order_types=res.data
          this.purchase_type = this.purchase_order_types[0]
        }
      })
    },
    getBranchSubSites (branch_site_id, index) {
      this.addExpense[index].branch_sub_site_id = null;
      this.http.get('level-one-chart-of-accounts/branch-sub-sites/'+  branch_site_id ).then(resp => {
        this.addExpense[index].branch_sub_sites = resp.data;
      });
    },
  },
  computed: {

    
  },
  created() {
    this.getBranches()
    this.getPurchaseOrderTypes()
  },
  mounted() {
     this.user=JSON.parse(localStorage.currentUser) 
    console.log("user :",this.user);
  },
};
</script>

