                  @complete="selectedAgent($event.query)"
                  :optionLabel="showAccountLabel"
                  :completeOnFocus="true"
                  class="w-100 from-control"
                :inputClass="'w-100 from-control'"
                />
              </div>
              <div class="col">
              <label for="asset_id">{{ $t("popups.po_ref_no") }}</label><br />
