                    id="t1"
                    :value="type"
                  />
                  <label class="form-check-label" for="t1">{{$i18n.locale =='en'? type.name_en: type.name}}</label>
                </div>
         
         
              </div>
             
            </div>
                <div class="row mb-2">
                  <div class="col-10">
                    <label for="asset_id">{{
                      $t("purchases.chose_items")
                    }}</label>
                  </div>
                  <div class="col-2">
                    <button
                      type="button"
                      @click="addExpense.push({})"
